import { _decorator, Component } from 'cc';
import { CoinEvents, CoinEventName } from './CoinEvents';
const { ccclass } = _decorator;

@ccclass('_TempTriggerTest')
export class _TempTriggerTest extends Component {
    fire(triggerId: number) {
        CoinEvents.emit(CoinEventName.SocketFilled, triggerId);
    }
}
